 110:         }
 111:         # Bounded representative HOME paths, not a second copy of the specification.
 112:         # List-flow fixtures are not direct home links; select detail cards separately.
 113:         targets = []
 114:         groups = (
 115:             ('repository', nodes, r'\bpublic repository\s+`([^`]+)`', 3),
 116:             ('issue', [by_name.get('View an Issue and Its Discussion', {})],
 117:              r'\b(?:Open\s+)?issue\s+(?:titled\s+)?`([^`]+)`', 1),
 118:             ('pull', [by_name.get(name, {}) for name in (
 119:                 'View Pull Request Overview and Commits', 'Inspect Changed Files and Aggregate Diff')],
 120:              r'\b(?:Open\s+)?(?:PR|pull request)\s+(?:titled\s+)?`([^`]+)`', 2),
 121:         )
 122:         for kind, selected, pattern, limit in groups:
 123:             found = {}
 124:             for node in selected:
 125:                 text = given_text(node)
 126:                 if 'unauthenticated' not in text.lower():
 127:                     continue
 128:                 if kind == 'repository' and not re.search(r'(?:application\s+)?home page', text, re.I):
 129:                     continue
 130:                 for label in re.findall(pattern, text, re.I):
 131:                     found.setdefault(label, []).extend(sources(node))
 132:             for label, ids in list(found.items())[:limit]:
 133:                 targets.append(dict(kind=kind, label=label, source_ids=list(dict.fromkeys(ids))))
 134:             if len(found) > limit:
 135:                 config.setdefault('deferred_home_targets', []).extend(list(found)[limit:])
 136:         config['home_targets'] = targets
 137:         menu = by_name.get('Create an Organization After Authentication', {})
 138:         if menu:
 139:             config['account_menu'] = {'account': named_account(menu) or config.get('account'),
 140:                                       'source_ids': sources(menu)}
 141:         compare = by_name.get('Create a Pull Request from Comparison Results', {})
 142:         if compare and '`Compare`' in given_text(compare):
 143:             config['compare_entry'] = {'account': named_account(compare), 'source_ids': sources(compare)}
 144:     path = workspace / '.arc/checks/public-prerequisites.json'
 145:     path.parent.mkdir(parents=True, exist_ok=True)
 146:     path.write_text(json.dumps(config, ensure_ascii=False, indent=2), encoding='utf-8')
