  24:   if (deadline - Date.now() < 5000) {
  25:     report.prerequisites.push({ name, ok: null, status: 'skipped', reason: 'Browser time reserve exhausted', source_ids: sourceIds });
  26:     return;
  27:   }
  28:   const context = await browser.newContext(options);
  29:   const page = await context.newPage();
  30:   watchPage(page);
  31:   page.setDefaultTimeout(2500);
  32:   page.setDefaultNavigationTimeout(5000);
  33:   let timer;
  34:   try {
  35:     await Promise.race([
  36:       (async () => { await page.goto(base + '/'); await execute(page); })(),
  37:       new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('ARC_CHECK_DEADLINE')), Math.max(1, deadline - Date.now())); }),
  38:     ]);
  39:     report.prerequisites.push({ name, ok: true, status: 'passed', source_ids: sourceIds });
